# Missing-Record Recovery Assistant demo: systematic sweep across fallbacks.
PRIMARY={}; REPLICA={"r1":"body-v2"}; SNAP={"r1":"body-v1"}; RENAMES={"old-r1":"r1"}
def recover(rid):
    trail=[]
    if rid in PRIMARY: return {"found":True,"via":"primary","trail":trail}
    trail.append("primary:miss")
    if rid in REPLICA: return {"found":True,"via":"replica","body":REPLICA[rid],"trail":trail+["replica:hit"]}
    trail.append("replica:miss")
    if rid in SNAP: return {"found":True,"via":"snapshot","body":SNAP[rid],"trail":trail+["snapshot:hit"]}
    trail.append("snapshot:miss")
    if rid in RENAMES: return {"found":True,"via":"rename->"+RENAMES[rid],"trail":trail}
    return {"found":False,"trail":trail+["rename-log:miss"]}
for q in ["r1","old-r1","rX"]:
    r=recover(q); print(q,r["found"],r.get("via"),"|"," ".join(r["trail"]))

